import { expect, type Locator, type Page } from '@playwright/test';

export class LoginPage {
  readonly page: Page;
  readonly emailInput: Locator;
  readonly passwordInput: Locator;
  readonly signInButton: Locator;
  readonly lockoutMessage: Locator;
  readonly resetPasswordLink: Locator;

  constructor(page: Page) {
    this.page = page;
    this.emailInput = page.getByTestId('login-email');
    this.passwordInput = page.getByTestId('login-password');
    this.signInButton = page.getByRole('button', { name: 'Sign in' });
    this.lockoutMessage = page.getByTestId('account-locked-message');
    this.resetPasswordLink = page.getByRole('link', { name: 'Reset your password' });
  }

  async goto() {
    await this.page.goto('/login');
  }

  async login(email: string, password: string) {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.signInButton.click();
  }

  async expectLocked() {
    await expect(this.lockoutMessage).toBeVisible();
    await expect(this.resetPasswordLink).toBeVisible();
  }
}

test_code:
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/login-page';

const SHOPPER = 'aurora.shopper@example.com';
const WRONG_PASSWORD = 'WrongPass123!';

test.describe('Account lockout', () => {
  test('locks the account after 5 consecutive failed attempts', async ({ page }) => {
    const login = new LoginPage(page);
    await login.goto();

    for (let attempt = 1; attempt <= 5; attempt++) {
      await login.login(SHOPPER, WRONG_PASSWORD);
    }

    await login.expectLocked();
  });

  test('rejects further attempts on a locked account', async ({ page }) => {
    const login = new LoginPage(page);
    await login.goto();
    await login.login(SHOPPER, WRONG_PASSWORD);
    await login.expectLocked();
  });
});

